-- Every public table's uuid columns must be the shape `z.uuid()` accepts:
-- version [1-8], variant [89ab], case-insensitive hex, plus the nil and max
-- literals zod also allows.
--
-- WHY: Postgres's `uuid` type accepts ANY 8-4-4-4-12 hex string, but `shared/`
-- validates stored ids with z.uuid() and the frontend parses whole lists with
-- it. A value written out of band (ad-hoc SQL, a hash-sliced id generator) is
-- therefore storable but unparseable, and ONE such row breaks /api/tasks and
-- /api/notifications for every reader — the page dies blaming the network.
-- This constraint makes the write fail loudly instead. See
-- `backend/src/db/schema/sql-uuid.ts`.
--
-- PRECONDITION: ADD CONSTRAINT validates existing rows, so a database still
-- holding a non-conformant id will fail here. Repair first (rewrite the value
-- to a conformant v5 derived from the old one, repointing referrers in the same
-- transaction), then re-run. Local dev and production were both clean when this
-- shipped; a database that fails here is telling you it is not.
ALTER TABLE "ai_run" ADD CONSTRAINT "ai_run_uuid_shape_check" CHECK (("ai_run"."id" IS NULL OR "ai_run"."id"::text ~ '^(00000000-0000-0000-0000-000000000000|ffffffff-ffff-ffff-ffff-ffffffffffff|[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-8][0-9a-fA-F]{3}-[89abAB][0-9a-fA-F]{3}-[0-9a-fA-F]{12})$') AND ("ai_run"."channel_id" IS NULL OR "ai_run"."channel_id"::text ~ '^(00000000-0000-0000-0000-000000000000|ffffffff-ffff-ffff-ffff-ffffffffffff|[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-8][0-9a-fA-F]{3}-[89abAB][0-9a-fA-F]{3}-[0-9a-fA-F]{12})$') AND ("ai_run"."user_id" IS NULL OR "ai_run"."user_id"::text ~ '^(00000000-0000-0000-0000-000000000000|ffffffff-ffff-ffff-ffff-ffffffffffff|[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-8][0-9a-fA-F]{3}-[89abAB][0-9a-fA-F]{3}-[0-9a-fA-F]{12})$'));--> statement-breakpoint
